INSERT INTO `services` (`id`, `title`, `desc`, `framework`, `img`, `created_at`, `updated_at`) VALUES
	(1, 'Nature Guide', 'A cross-platform fitness application that helps users track their workouts, set goals, and connect with friends. The app includes features like workout plans, progress tracking, and social sharing to keep users motivated.', 'React Js', 'IXBAc0eVAnABRhZ3o7Gd9gIU64PRz7c5b3CIplUm.png', '2025-03-19 03:22:07', '2025-03-19 03:22:07'),
	(3, 'SI-Dihimens', 'A comprehensive real estate platform that connects buyers, sellers, and agents. Features include property listings, advanced search filters, virtual tours, and appointment scheduling. The platform uses AI to provide personalized property recommendations.', 'Next JS', 'VUGvk2ChKrwbxuOSSCRgKA7jCKzc2PnPU8H5p2Q9.png', '2025-03-19 03:24:35', '2025-03-19 03:24:35'),
	(4, 'Recything', 'A comprehensive e-commerce solution with advanced product filtering, user authentication, and a seamless checkout process. This platform was built with performance and scalability in mind.', 'React Js', 'HoqUh6vkdXTeMnnWV0ouuNEOaqPqfaPpWmgOmTRL.jpg', '2025-03-19 03:25:31', '2025-03-19 03:25:31'),
	(5, 'E-RD', 'A cross-platform fitness application that helps users track their workouts, set goals, and connect with friends. The app includes features like workout plans, progress tracking, and social sharing to keep users motivated.', 'Vue JS', 'MN4bnX5lCMF2xRyQpWelPKZEKvUj5nfjiMFTtkaD.jpg', '2025-03-19 03:25:56', '2025-03-19 03:25:56');
